{"t":"say","text":"I'll design a fully serverless REST API using Function Compute and API Gateway, scaling to zero for spiky traffic."}
{"t":"plan","products":["mobile-app","dns","cloud-native-api-gateway","fc","tablestore","oss","sls"]}
{"t":"assume","id":"region","text":"Singapore region","alt":"Another region"}
{"t":"assume","id":"auth","text":"API key or JWT auth at gateway","alt":"Custom auth in functions"}
{"t":"group","id":"internet","kind":"external","label":"Internet","parent":null}
{"t":"node","id":"app","product":"mobile-app","label":"Mobile app","group":"internet","why":"End users calling the REST API."}
{"t":"node","id":"dns","product":"dns","label":"Cloud DNS","group":null,"why":"Resolves API domain to the gateway."}
{"t":"edge","id":"e-app-dns","from":"app","to":"dns","kind":"resolve"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"API VPC","parent":"sg"}
{"t":"node","id":"gw","product":"cloud-native-api-gateway","label":"API Gateway","group":"vpc","why":"Routes REST calls, throttles spikes, handles auth."}
{"t":"edge","id":"e-app-gw","from":"app","to":"gw","label":"HTTPS"}
{"t":"node","id":"api","product":"fc","label":"API functions","group":"vpc","why":"Serverless compute scales to zero, pay per request."}
{"t":"edge","id":"e-gw-api","from":"gw","to":"api","label":"invoke"}
{"t":"node","id":"db","product":"tablestore","label":"Data store","group":"sg","why":"Serverless NoSQL, no idle cost, auto-scales with traffic."}
{"t":"edge","id":"e-api-db","from":"api","to":"db","label":"read/write"}
{"t":"node","id":"files","product":"oss","label":"Object storage","group":"sg","why":"Stores uploads and static assets serverlessly."}
{"t":"edge","id":"e-api-files","from":"api","to":"files","label":"objects"}
{"t":"node","id":"logs","product":"sls","label":"Logs","group":"sg","why":"Collects function logs and API traces."}
{"t":"edge","id":"e-api-logs","from":"api","to":"logs","kind":"control"}
{"t":"ask","id":"payload-size","text":"Are requests mostly small JSON, or do they include large file uploads?","options":["Small JSON only","Large file uploads"]}
{"t":"ask","id":"latency","text":"Do you need cold-start latency under 100ms?","options":["Yes, low latency","Standard is fine"]}
{"t":"done","summary":"Serverless REST API with Cloud-native API Gateway, Function Compute, Tablestore and OSS, paying only per use."}

{"t":"say","text":"I'll draw an ACK-based Kubernetes platform for your 20 Java microservices with MSE Nacos, API Gateway, RocketMQ, Tair and PolarDB."}
{"t":"plan","products":["users","dns","alb","cloud-native-api-gateway","ack","mse","rocketmq","tair","polardb","sls","arms"]}
{"t":"assume","id":"public-entry","text":"Public-facing API entry point","alt":"Internal-only access via VPN"}
{"t":"assume","id":"region","text":"Singapore region deployment","alt":"Another international region"}
{"t":"group","id":"internet","kind":"external","label":"Internet","parent":null}
{"t":"node","id":"users","product":"users","label":"API clients","group":"internet","why":"External consumers calling the microservices APIs."}
{"t":"node","id":"dns","product":"dns","label":"Alibaba Cloud DNS","group":null,"why":"Resolves the API domain to the ALB."}
{"t":"edge","id":"e-users-dns","from":"users","to":"dns","kind":"resolve"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Microservices VPC","parent":"sg"}
{"t":"node","id":"alb","product":"alb","label":"ALB","group":"vpc","zones":["a","b"],"why":"Ingress load balancer distributing traffic across zones."}
{"t":"edge","id":"e-users-alb","from":"users","to":"alb","label":"HTTPS"}
{"t":"node","id":"gateway","product":"cloud-native-api-gateway","label":"Cloud-native API Gateway","group":"vpc","zones":["a","b"],"why":"Single API entry point with auth and throttling for all services."}
{"t":"edge","id":"e-alb-gateway","from":"alb","to":"gateway"}
{"t":"node","id":"ack","product":"ack","label":"ACK cluster","group":"vpc","zones":["a","b"],"why":"Runs the 20 Java microservices as Kubernetes workloads."}
{"t":"edge","id":"e-gateway-ack","from":"gateway","to":"ack","label":"routes"}
{"t":"node","id":"mse","product":"mse","label":"MSE Nacos","group":"vpc","zones":["a","b"],"why":"Service discovery and centralized configuration for all microservices."}
{"t":"edge","id":"e-ack-mse","from":"ack","to":"mse","label":"discovery",kind":"control"}
{"t":"node","id":"mq","product":"rocketmq","label":"ApsaraMQ for RocketMQ","group":"vpc","zones":["a","b"],"why":"Async messaging between microservices for decoupled communication."}
{"t":"edge","id":"e-ack-mq","from":"ack","to":"mq","label":"events",kind":"async"}
{"t":"node","id":"cache","product":"tair","label":"Tair cache","group":"vpc","zones":["a","b"],"why":"In-memory cache shared across services for fast data access."}
{"t":"edge","id":"e-ack-cache","from":"ack","to":"cache","label":"read/write"}
{"t":"node","id":"db","product":"polardb","label":"PolarDB","group":"vpc","zones":["a","b"],"why":"Relational database with compute-storage separation for all services."}
{"t":"edge","id":"e-ack-db","from":"ack","to":"db","label":"SQL"}
{"t":"node","id":"logs","product":"sls","label":"Simple Log Service","group":"sg","why":"Centralized log collection and analysis for all microservices."}
{"t":"edge","id":"e-ack-logs","from":"ack","to":"logs","kind":"control"}
{"t":"node","id":"monitor","product":"arms","label":"ARMS","group":"sg","why":"APM tracing and monitoring for the Java microservices."}
{"t":"edge","id":"e-ack-monitor","from":"ack","to":"monitor","kind":"control"}
{"t":"ask","id":"db-engine","text":"Which database engine do your Java services use?","options":["MySQL","PostgreSQL","Oracle-compatible"]}
{"t":"ask","id":"team-k8s-exp","text":"Does your team have Kubernetes experience, or prefer a serverless PaaS like SAE?","options":["Yes, we know Kubernetes","No, prefer serverless PaaS"]}
{"t":"done","summary":"Kubernetes platform on ACK with MSE Nacos, Cloud-native API Gateway, RocketMQ, Tair and PolarDB for 20 Java microservices."}

{"t":"say","text":"I'll design a highly available online store in Singapore with ESA for acceleration, ALB with WAF, auto-scaling ECS, Tair cache and PolarDB."}
{"t":"plan","products":["users","dns","esa","alb","waf","ecs","ess","tair","polardb","oss","sls","cloudmonitor"]}
{"t":"assume","id":"public-access","text":"Public-facing store accessible over the internet","alt":"Internal-only access via VPN"}
{"t":"assume","id":"new-build","text":"New build entirely on Alibaba Cloud","alt":"Hybrid with existing on-premises systems"}
{"t":"group","id":"internet","kind":"external","label":"Internet","parent":null}
{"t":"node","id":"users","product":"users","label":"Shoppers","group":"internet","why":"30k daily users browsing and buying from Southeast Asia."}
{"t":"node","id":"dns","product":"dns","label":"Cloud DNS","group":null,"why":"Resolves the store domain to ESA edge nodes."}
{"t":"edge","id":"e-users-dns","from":"users","to":"dns","kind":"resolve"}
{"t":"group","id":"edge","kind":"edge","label":"Edge","parent":null}
{"t":"node","id":"esa","product":"esa","label":"ESA","group":"edge","why":"Caches static assets and accelerates dynamic API calls across Southeast Asia."}
{"t":"edge","id":"e-users-esa","from":"users","to":"esa","label":"HTTPS"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Store VPC","parent":"sg"}
{"t":"node","id":"alb","product":"alb","label":"ALB","group":"vpc","zones":["a","b"],"why":"Distributes traffic across two zones for high availability."}
{"t":"node","id":"waf","product":"waf","label":"WAF","group":"vpc","attachTo":"alb","why":"Protects against OWASP attacks, bots and CC floods during sales peaks."}
{"t":"edge","id":"e-esa-alb","from":"esa","to":"alb","label":"origin"}
{"t":"node","id":"app","product":"ecs","label":"App servers","group":"vpc","zones":["a","b"],"why":"Runs the store backend across two zones for fault tolerance."}
{"t":"node","id":"scaling","product":"ess","label":"Auto Scaling","group":"vpc","attachTo":"app","why":"Automatically adds instances during big sales peaks."}
{"t":"edge","id":"e-alb-app","from":"alb","to":"app"}
{"t":"say","text":"Sessions go to Tair and product data to PolarDB, both multi-zone for resilience."}
{"t":"node","id":"cache","product":"tair","label":"Session cache","group":"vpc","zones":["a","b"],"why":"Stores sessions and hot cart data for fast checkout."}
{"t":"node","id":"db","product":"polardb","label":"Product DB","group":"vpc","zones":["a","b"],"why":"Cloud-native database with instant read scale-out for sales peaks."}
{"t":"edge","id":"e-app-cache","from":"app","to":"cache"}
{"t":"edge","id":"e-app-db","from":"app","to":"db","label":"SQL"}
{"t":"node","id":"media","product":"oss","label":"Product images","group":"sg","why":"Stores product images and assets served by ESA."}
{"t":"edge","id":"e-esa-media","from":"esa","to":"media","label":"images"}
{"t":"say","text":"Adding monitoring and logging for observability."}
{"t":"node","id":"logs","product":"sls","label":"Logs","group":"sg","why":"Centralizes application logs for troubleshooting and alerting."}
{"t":"node","id":"metrics","product":"cloudmonitor","label":"CloudMonitor","group":"sg","why":"Monitors resource metrics and triggers scaling alarms."}
{"t":"edge","id":"e-app-logs","from":"app","to":"logs","kind":"control"}
{"t":"edge","id":"e-metrics-app","from":"metrics","to":"app","kind":"control"}
{"t":"ask","id":"peak-scale","text":"How many concurrent users do you expect during your biggest sales peaks?","options":["50,000","100,000","Over 500,000"]}
{"t":"ask","id":"payment-gateway","text":"Which payment gateway or method does your store use?","options":["Third-party API (Stripe, etc.)","Alibaba Cloud integration","Custom payment service"]}
{"t":"done","summary":"Highly available store in Singapore with ESA, ALB plus WAF, auto-scaling ECS in two zones, Tair cache, PolarDB and OSS for media."}

{"t":"say","text":"I'll draw a private RAG assistant on ACK with Dify, Qwen models and a vector store over your policy docs."}
{"t":"plan","products":["users","dns","vpc","alb","ack","dify-on-ack","rds","tair","model-studio","milvus","oss","nat","sls"]}
{"t":"assume","id":"hosting","text":"Self-hosted on Alibaba Cloud for full control","alt":"Use AgentCore managed platform"}
{"t":"assume","id":"region","text":"Singapore region for Model Studio access","alt":"Another supported region"}
{"t":"group","id":"internal","kind":"external","label":"Internal network","parent":null}
{"t":"node","id":"users","product":"users","label":"Employees","group":"internal","why":"Staff asking questions about policies and wiki."}
{"t":"node","id":"dns","product":"privatezone","label":"Private DNS","group":null,"why":"Resolves internal assistant domain inside VPC."}
{"t":"edge","id":"e-users-dns","from":"users","to":"dns","kind":"resolve"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Assistant VPC","parent":"sg"}
{"t":"node","id":"alb","product":"alb","label":"ALB","group":"vpc","zones":["a","b"],"why":"Internal load balancer for the assistant UI."}
{"t":"edge","id":"e-users-alb","from":"users","to":"alb","label":"HTTPS"}
{"t":"node","id":"ack","product":"ack","label":"ACK cluster","group":"vpc","zones":["a","b"],"why":"Runs Dify and supporting services."}
{"t":"edge","id":"e-alb-ack","from":"alb","to":"ack"}
{"t":"node","id":"dify","product":"dify-on-ack","label":"Dify assistant","group":"vpc","why":"Low-code RAG builder hosting the Q&A workflow."}
{"t":"edge","id":"e-ack-dify","from":"ack","to":"dify"}
{"t":"say","text":"Dify retrieves from Milvus, stores state in RDS and Tair, and calls Qwen through NAT."}
{"t":"node","id":"vector","product":"milvus","label":"Milvus vector store","group":"vpc","zones":["a","b"],"why":"Holds embeddings of policy docs and wiki pages."}
{"t":"edge","id":"e-dify-vector","from":"dify","to":"vector","label":"search"}
{"t":"node","id":"db","product":"rds","label":"RDS PostgreSQL","group":"vpc","zones":["a","b"],"why":"Stores Dify metadata, users and chat history."}
{"t":"edge","id":"e-dify-db","from":"dify","to":"db","label":"SQL"}
{"t":"node","id":"cache","product":"tair","label":"Tair cache","group":"vpc","zones":["a","b"],"why":"Caches sessions and frequent lookups."}
{"t":"edge","id":"e-dify-cache","from":"dify","to":"cache"}
{"t":"node","id":"docs","product":"oss","label":"Policy documents","group":"sg","why":"Stores uploaded PDFs and wiki exports for ingestion."}
{"t":"edge","id":"e-dify-docs","from":"dify","to":"docs","label":"read"}
{"t":"node","id":"nat","product":"nat","label":"NAT Gateway","group":"vpc","why":"Gives Dify outbound access to Model Studio APIs."}
{"t":"edge","id":"e-dify-nat","from":"dify","to":"nat","label":"outbound"}
{"t":"node","id":"llm","product":"model-studio","label":"Model Studio","group":"sg","why":"Hosts Qwen models for generation and embedding."}
{"t":"edge","id":"e-nat-llm","from":"nat","to":"llm","label":"API"}
{"t":"node","id":"logs","product":"sls","label":"SLS logs","group":"sg","why":"Collects assistant usage and error logs."}
{"t":"edge","id":"e-dify-logs","from":"dify","to":"logs","kind":"control"}
{"t":"ask","id":"doc-source","text":"How will you feed policy docs and wiki content into the assistant?","options":["Manual upload to OSS","Automated sync from existing wiki","Both"]}
{"t":"ask","id":"auth","text":"How should employees authenticate to the assistant?","options":["SSO via IDaaS","Existing corporate SSO","No auth for now"]}
{"t":"done","summary":"Internal RAG assistant on ACK with Dify, Milvus, RDS, Tair and Qwen via Model Studio behind an internal ALB."}

{"t":"say","text":"I'll draw a data platform that replicates MySQL in real time via DTS, runs nightly batch in MaxCompute, and serves dashboards with Hologres and Quick BI."}
{"t":"plan","products":["rds","dts","maxcompute","dataworks","hologres","quick-bi","users","oss"]}
{"t":"assume","id":"source-db","text":"Source is an existing RDS MySQL order database","alt":"External MySQL on-premises or another cloud"}
{"t":"assume","id":"region","text":"Deployed in Singapore (ap-southeast-1)","alt":"Another international region"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Data Platform VPC","parent":"sg"}
{"t":"node","id":"orders-db","product":"rds","label":"Orders MySQL","group":"vpc","zones":["a","b"],"why":"Source order database to replicate from."}
{"t":"node","id":"dts","product":"dts","label":"DTS Sync","group":"sg","why":"Real-time CDC replication from MySQL to the warehouse."}
{"t":"edge","id":"e-orders-dts","from":"orders-db","to":"dts","label":"CDC","kind":"async"}
{"t":"node","id":"warehouse","product":"maxcompute","label":"MaxCompute Warehouse","group":"sg","why":"Stores replicated orders and runs nightly batch analytics."}
{"t":"edge","id":"e-dts-warehouse","from":"dts","to":"warehouse","label":"sync","kind":"async"}
{"t":"node","id":"orchestrator","product":"dataworks","label":"DataWorks","group":"sg","why":"Schedules nightly ETL jobs over MaxCompute tables."}
{"t":"edge","id":"e-orchestrator-warehouse","from":"orchestrator","to":"warehouse","label":"ETL","kind":"control"}
{"t":"node","id":"lake","product":"oss","label":"Data Lake OSS","group":"sg","why":"Holds raw extracts and DataWorks job artifacts."}
{"t":"edge","id":"e-orchestrator-lake","from":"orchestrator","to":"lake","label":"artifacts","kind":"data"}
{"t":"node","id":"serving","product":"hologres","label":"Hologres Serving","group":"vpc","zones":["a","b"],"why":"Interactive serving layer for sub-second dashboard queries."}
{"t":"edge","id":"e-warehouse-serving","from":"warehouse","to":"serving","label":"nightly load","kind":"async"}
{"t":"group","id":"external","kind":"external","label":"Business Users","parent":null}
{"t":"node","id":"analysts","product":"users","label":"Business Analysts","group":"external","why":"Users exploring dashboards and reports."}
{"t":"node","id":"bi","product":"quick-bi","label":"Quick BI Dashboards","group":null,"why":"BI dashboards connected to Hologres for business users."}
{"t":"edge","id":"e-analysts-bi","from":"analysts","to":"bi","label":"browse"}
{"t":"edge","id":"e-bi-serving","from":"bi","to":"serving","label":"SQL queries","kind":"data"}
{"t":"ask","id":"source-location","text":"Where does your source MySQL database currently run?","options":["Alibaba Cloud RDS","On-premises","Another cloud provider"]}
{"t":"ask","id":"latency-need","text":"Do dashboards need real-time data or is a nightly refresh acceptable?","options":["Nightly refresh is fine","Near real-time (minutes)"]}
{"t":"done","summary":"Data platform with DTS real-time sync into MaxCompute, DataWorks nightly orchestration, Hologres serving and Quick BI dashboards."}

{"t":"say","text":"I'll design a real-time IoT telemetry pipeline: devices publish to IoT Platform, Flink detects anomalies, and DataV shows the live dashboard."}
{"t":"plan","products":["iot-devices","iot-platform","kafka","flink","tair","tablestore","sls","datav","arms"]}
{"t":"assume","id":"region","text":"Singapore region for all workloads","alt":"Another international region"}
{"t":"assume","id":"protocol","text":"Devices connect over MQTT","alt":"CoAP or HTTPS"}
{"t":"group","id":"field","kind":"external","label":"Field","parent":null}
{"t":"node","id":"devices","product":"iot-devices","label":"100k IoT devices","group":"field","why":"Sensors publishing telemetry every few seconds."}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"IoT VPC","parent":"sg"}
{"t":"node","id":"iot","product":"iot-platform","label":"IoT Platform","group":"sg","why":"Ingests MQTT telemetry from 100k devices and forwards to Kafka."}
{"t":"edge","id":"e-devices-iot","from":"devices","to":"iot","label":"MQTT","kind":"data"}
{"t":"node","id":"kafka","product":"kafka","label":"Kafka","group":"vpc","zones":["a","b"],"why":"Buffers high-throughput telemetry for stream processing."}
{"t":"edge","id":"e-iot-kafka","from":"iot","to":"kafka","label":"telemetry","kind":"data"}
{"t":"node","id":"flink","product":"flink","label":"Flink","group":"vpc","why":"Runs real-time SQL to detect anomalies in telemetry streams."}
{"t":"edge","id":"e-kafka-flink","from":"kafka","to":"flink","label":"stream","kind":"data"}
{"t":"node","id":"cache","product":"tair","label":"Tair cache","group":"vpc","zones":["a","b"],"why":"Holds latest device state and anomaly flags for the dashboard."}
{"t":"edge","id":"e-flink-cache","from":"flink","to":"cache","label":"state","kind":"data"}
{"t":"node","id":"tsdb","product":"tablestore","label":"Tablestore","group":"sg","why":"Stores raw time-series telemetry at massive scale cheaply."}
{"t":"edge","id":"e-flink-tsdb","from":"flink","to":"tsdb","label":"write","kind":"data"}
{"t":"node","id":"logs","product":"sls","label":"SLS","group":"sg","why":"Collects alert logs and enables search on anomaly events."}
{"t":"edge","id":"e-flink-logs","from":"flink","to":"logs","label":"alerts","kind":"async"}
{"t":"node","id":"dashboard","product":"datav","label":"DataV dashboard","group":"sg","why":"Renders a live large-screen view of device health and anomalies."}
{"t":"edge","id":"e-cache-dashboard","from":"cache","to":"dashboard","label":"live data","kind":"data"}
{"t":"node","id":"monitor","product":"arms","label":"ARMS","group":"sg","why":"Monitors Flink and Kafka pipeline health with alerts."}
{"t":"edge","id":"e-flink-monitor","from":"flink","to":"monitor","kind":"control"}
{"t":"ask","id":"alert-channel","text":"How should anomaly alerts be delivered to operators?","options":["SMS via SMS service","DingTalk webhook","Email via Direct Mail"]}
{"t":"ask","id":"device-auth","text":"How are the 100k devices authenticated?","options":["X.509 certificates","Device secrets","Custom token server"]}
{"t":"done","summary":"Real-time IoT pipeline: IoT Platform ingests MQTT, Kafka buffers, Flink detects anomalies, Tair feeds a DataV live dashboard, Tablestore stores history."}

{"t":"say","text":"I'll draw your on-premises data center connected to a Singapore VPC via Express Connect, with SMC and DTS for step-by-step VM migration."}
{"t":"plan","products":["onprem-dc","express-connect","vpc","ecs","smc","dts","rds"]}
{"t":"assume","id":"link-type","text":"Dedicated private line via Express Connect","alt":"Encrypted tunnel via VPN Gateway"}
{"t":"assume","id":"vm-db","text":"VMs include databases needing sync","alt":"Stateless VMs only"}
{"t":"group","id":"onprem","kind":"onprem","label":"On-premises DC (Singapore)","parent":null}
{"t":"node","id":"onprem-dc","product":"onprem-dc","label":"On-premises data center","group":"onprem","why":"Your existing servers and workloads in Singapore."}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Cloud VPC","parent":"sg"}
{"t":"node","id":"ec","product":"express-connect","label":"Express Connect","group":"vpc","why":"Private dedicated link between on-premises and the VPC."}
{"t":"edge","id":"e-onprem-ec","from":"onprem-dc","to":"ec","label":"private link"}
{"t":"node","id":"target-vms","product":"ecs","label":"Migrated VMs (ECS)","group":"vpc","zones":["a","b"],"why":"Destination compute instances for migrated workloads."}
{"t":"edge","id":"e-ec-target","from":"ec","to":"target-vms","label":"VPC traffic"}
{"t":"node","id":"target-db","product":"rds","label":"Target database (RDS)","group":"vpc","zones":["a","b"],"why":"Managed database destination for migrated data."}
{"t":"edge","id":"e-target-targetdb","from":"target-vms","to":"target-db","label":"SQL"}
{"t":"say","text":"SMC migrates VM images and DTS keeps databases in sync during cutover."}
{"t":"node","id":"smc","product":"smc","label":"Server Migration Center","group":"sg","why":"Incrementally replicates on-prem VMs to ECS instances."}
{"t":"edge","id":"e-onprem-smc","from":"onprem-dc","to":"smc","label":"replicate","kind":"control"}
{"t":"edge","id":"e-smc-target","from":"smc","to":"target-vms","label":"deploy","kind":"control"}
{"t":"node","id":"dts","product":"dts","label":"Data Transmission Service","group":"sg","why":"Syncs on-prem databases to RDS with minimal downtime."}
{"t":"edge","id":"e-onprem-dts","from":"onprem-dc","to":"dts","label":"CDC","kind":"async"}
{"t":"edge","id":"e-dts-targetdb","from":"dts","to":"target-db","label":"sync","kind":"async"}
{"t":"ask","id":"bandwidth","text":"What bandwidth do you need for the private link?","options":["Under 1 Gbps","1-10 Gbps","Over 10 Gbps"]}
{"t":"ask","id":"source-os","text":"What operating systems are your on-prem VMs running?","options":["Linux","Windows","Mixed"]}
{"t":"done","summary":"On-premises Singapore DC linked to Alibaba Cloud VPC via Express Connect, with SMC for VM migration and DTS for database sync."}

{"t":"say","text":"I'll design a live-streaming and VOD platform for e-sports fans using ApsaraVideo Live, VOD, ESA for edge delivery, and OSS for storage."}
{"t":"plan","products":["users","dns","esa","live","vod","mps","oss","alb","ecs","rds","tair","sls"]}
{"t":"assume","id":"scale","text":"About 50k concurrent viewers","alt":"Over 500k concurrent viewers"}
{"t":"assume","id":"region","text":"Singapore region","alt":"Other region"}
{"t":"group","id":"internet","kind":"external","label":"Internet","parent":null}
{"t":"node","id":"users","product":"users","label":"E-sports fans","group":"internet","why":"Viewers watching streams and VOD content."}
{"t":"node","id":"dns","product":"dns","label":"Cloud DNS","group":null,"why":"Resolves platform domain to ESA."}
{"t":"edge","id":"e-users-dns","from":"users","to":"dns","kind":"resolve"}
{"t":"group","id":"edge","kind":"edge","label":"Edge","parent":null}
{"t":"node","id":"esa","product":"esa","label":"ESA","group":"edge","why":"Delivers live and VOD streams with low latency globally."}
{"t":"edge","id":"e-users-esa","from":"users","to":"esa","label":"HTTPS"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"node","id":"live","product":"live","label":"ApsaraVideo Live","group":"sg","why":"Ingests, transcodes and distributes live e-sports streams."}
{"t":"edge","id":"e-live-esa","from":"live","to":"esa","label":"stream"}
{"t":"node","id":"vod","product":"vod","label":"ApsaraVideo VOD","group":"sg","why":"Stores and delivers recorded matches on demand."}
{"t":"edge","id":"e-vod-esa","from":"vod","to":"esa","label":"playback"}
{"t":"node","id":"mps","product":"mps","label":"Media Processing","group":"sg","why":"Transcodes recordings into adaptive bitrate formats."}
{"t":"edge","id":"e-live-mps","from":"live","to":"mps","label":"recordings","kind":"async"}
{"t":"edge","id":"e-mps-vod","from":"mps","to":"vod","label":"transcoded","kind":"async"}
{"t":"node","id":"media","product":"oss","label":"Media storage","group":"sg","why":"Stores raw and processed video assets."}
{"t":"edge","id":"e-vod-media","from":"vod","to":"media","label":"assets"}
{"t":"group","id":"vpc","kind":"vpc","label":"Platform VPC","parent":"sg"}
{"t":"node","id":"alb","product":"alb","label":"ALB","group":"vpc","zones":["a","b"],"why":"Routes web and API traffic across zones."}
